// 🔹 Extract AI response safely
const candidates = [
aiState.output,
aiState.response,
aiState.text,
aiState.message,
aiState.result,
aiState.replyText,
aiState.content,
aiState.data?.output,
aiState.data?.text
]
.filter(v => typeof v === 'string')
.map(v => v.trim())
.filter(Boolean);

const aiReply = candidates[0] || '';

// 🔹 Normalize text
const normalizedUserText = String(input.text || '').trim().toLowerCase();
const normalizedAiText = String(aiReply || '').trim().toLowerCase();

// 🔹 Detect bad AI responses
const lowQualityReplies = ['ok', 'okay', 'yes', 'no', 'hmm', 'k', 'alright'];

const aiLooksLowQuality =
!normalizedAiText ||
normalizedAiText.length < 3 ||
lowQualityReplies.includes(normalizedAiText);

const aiLooksLikeEcho =
normalizedAiText &&
normalizedUserText &&
normalizedAiText === normalizedUserText;

// 🔹 Smart fallback
const fallbackReply = (() => {

if (detected.orderIntentHint === 'create' && detected.intent === 'greeting') {
return '🛒 What would you like to order?\n\nSend product name + quantity.';
}

if (detected.orderIntentHint === 'update' && detected.intent === 'greeting') {
return '✏️ Please send your Order ID and what you want to update.';
}

if (detected.orderIntentHint === 'delete' && detected.intent === 'greeting') {
return '❌ Send your Order ID to cancel your order.';
}

if (detected.orderIntentHint === 'status' && detected.intent === 'greeting') {
return '📦 Send your Order ID to check status.';
}

switch (detected.intent || input.intent || 'greeting') {

```
case 'create':
  return '🛒 Tell me the product name and quantity.';

case 'update':
  return '✏️ Share your Order ID to update it.';

case 'delete':
  return '❌ Share your Order ID to cancel it.';

case 'status':
  return '📦 Share your Order ID to track it.';

default:
  return 'Hi! 👋\n\nI can help you:\n🛒 Place orders\n✏️ Update orders\n❌ Cancel orders\n📦 Track orders\n\nWhat would you like to do?';
```

}

})();

// 🔹 Decision logic
let finalReply = aiReply;

if (!aiReply || aiLooksLikeEcho || aiLooksLowQuality) {
finalReply = fallbackReply;
}

// 🔹 Trim long replies
if (typeof finalReply === 'string' && finalReply.length > 400) {
finalReply = finalReply.slice(0, 400) + '...';
}

// 🔹 Telegram-safe formatting
finalReply = finalReply
.replace(/[*_`]/g, '')   // remove markdown conflicts
