).trim();

// ─────────────────────────────────────────────────────────────
// SESSION / CHAT ID
// ─────────────────────────────────────────────────────────────

const chatIdValue =
waMessage?.from ?? // WhatsApp phone
waContact?.wa_id ??
$json.message?.chat?.id ??
body.chat_id ??
body.chatId ??
body.session_id ??
body.user_id ??
body.phone ??
body.email ??
`web-${Date.now()}`;

const chatId = String(chatIdValue);

// ─────────────────────────────────────────────────────────────
// USER NAME
// ─────────────────────────────────────────────────────────────

const userName = String(
waContact?.profile?.name ??
$json.message?.from?.username ??
$json.message?.from?.first_name ??
body.user_name ??
body.username ??
body.name ??
''
).trim();

// ─────────────────────────────────────────────────────────────
// FULL NAME
// ─────────────────────────────────────────────────────────────

const fullName = String(
waContact?.profile?.name ??
[
$json.message?.from?.first_name,
$json.message?.from?.last_name
].filter(Boolean).join(' ') ||
body.full_name ||
body.name ||
userName
).trim();

// ─────────────────────────────────────────────────────────────
// CUSTOMER DETAILS
// ─────────────────────────────────────────────────────────────

const email = String(
body.email ??
body.customerEmail ??
''
).trim();

const phone = String(
waMessage?.from ??
waContact?.wa_id ??
body.phone ??
body.mobile ??
''
).trim();

const address = String(
body.address ??
body.shippingAddress ??
body.deliveryAddress ??
''
).trim();

