body.paymentMethod ??
body.payment ??
''
).trim();

const paymentStatus = String(
body.paymentStatus ??
'Pending'
).trim();

const transactionId = String(
body.transactionId ??
''
).trim();

// ─────────────────────────────────────────────────────────────
// ORDER DETAILS
// ─────────────────────────────────────────────────────────────

const orderId = String(
body.orderId ??
''
).trim();

const itemName = String(
body.itemName ??
body.product ??
''
).trim();

const quantity = Number(
body.quantity ??
1
);

const variant = String(
body.variant ??
body.size ??
body.color ??
''
).trim();

// ─────────────────────────────────────────────────────────────
// PROFILE FLAGS
// ─────────────────────────────────────────────────────────────

const hasEmail = !!email;
const hasPhone = !!phone;
const hasAddress = !!address;

