json: {
source,

```
text,

sessionId: chatId,
chatId,

userName,
fullName,

email,
phone,
address,

paymentMethod,
paymentStatus,
transactionId,

orderId,
itemName,
quantity,
variant,

hasEmail,
hasPhone,
hasAddress,
